<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);if($_SERVER['REQUEST_METHOD']!=='POST')redirect_to('fakultas.php');csrf_verify();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$st=mysqli_prepare($koneksi,"SELECT COUNT(*) total FROM program_studi WHERE id_fakultas=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$x=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if($x['total']>0){flash('error','Fakultas tidak dapat dihapus karena masih memiliki Program Studi.');redirect_to('fakultas.php');}$st=mysqli_prepare($koneksi,"DELETE FROM fakultas WHERE id_fakultas=?");mysqli_stmt_bind_param($st,'i',$id);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'fakultas',(string)$id,'DELETE');flash('success','Fakultas berhasil dihapus.');}else flash('error','Gagal menghapus fakultas.');redirect_to('fakultas.php');